-- 1. 开启慢日志并设置阈值（生产排查时临时调低，排查完调回）
SET GLOBAL slow_query_log = ON;
SET GLOBAL long_query_time = 0.1;
SET GLOBAL log_queries_not_using_indexes = ON;

-- 2. 用 pt-query-digest 聚合慢日志（在 shell 中执行）
-- pt-query-digest /var/lib/mysql/slow.log --order-by Query_time:sum

-- 3. 找到高耗时 SQL 后看执行路径
EXPLAIN ANALYZE SELECT *
FROM orders
WHERE user_id = 7
ORDER BY created_at DESC
LIMIT 20;

-- 4. 如果 type=ALL 且 Extra=Using filesort，加联合索引
CREATE INDEX idx_uid_created ON orders(user_id, created_at);

-- 5. 深分页改写：游标分页
-- 慢：SELECT * FROM orders ORDER BY id LIMIT 100000, 10;
-- 快：SELECT * FROM orders WHERE id > 100000 ORDER BY id LIMIT 10;

-- 6. 深分页改写：延迟关联
SELECT t.* FROM orders t
INNER JOIN (
    SELECT id FROM orders ORDER BY id LIMIT 100000, 10
) tmp ON t.id = tmp.id;

-- 7. 刷新统计信息（优化器估算偏差大时）
ANALYZE TABLE orders;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ThreadLocalRandom;

/**
 * 演示分库分表后三个核心问题：路由、全局 ID、跨分片查询归并
 */
public class ShardingDemo {

    /** 路由：按 user_id 取模确定分片 */
    static int routeToShard(long userId, int shardCount) {
        return (int) (Math.abs(userId) % shardCount);
    }

    /** Snowflake 全局 ID（简化版，41 位时间戳 + 10 位机器 + 12 位序列） */
    static class Snowflake {
        private final long epoch = 1700000000000L;
        private final long machineId;
        private long sequence = 0;
        private long lastTimestamp = -1;

        Snowflake(long machineId) {
            this.machineId = machineId & 0x3FF; // 10 bit
        }

        synchronized long nextId() {
            long ts = System.currentTimeMillis() - epoch;
            if (ts == lastTimestamp) {
                sequence = (sequence + 1) & 0xFFF; // 12 bit
                if (sequence == 0) {
                    while (ts <= lastTimestamp) ts = System.currentTimeMillis() - epoch;
                }
            } else {
                sequence = 0;
            }
            lastTimestamp = ts;
            return (ts << 22) | (machineId << 12) | sequence;
        }
    }

    /** 跨分片 Top-N 归并：各分片取 Top-N 后在应用层合并排序 */
    static <T extends Comparable<T>> List<T> mergeTopN(List<List<T>> shardResults, int n) {
        List<T> merged = new ArrayList<>();
        for (List<T> shard : shardResults) {
            merged.addAll(shard);
        }
        merged.sort(null);
        return merged.subList(0, Math.min(n, merged.size()));
    }

    public static void main(String[] args) {
        // 路由示例
        System.out.println("user 12345 -> shard " + routeToShard(12345, 4)); // shard 1

        // 全局 ID 示例
        Snowflake snowflake = new Snowflake(1);
        System.out.println("snowflake id: " + snowflake.nextId());

        // 跨分片归并示例
        List<List<Integer>> results = List.of(
            List.of(1, 3, 5, 7, 9),
            List.of(2, 4, 6, 8, 10)
        );
        System.out.println("top 3: " + mergeTopN(results, 3)); // [1, 2, 3]
    }
}
